     1→// ============================================================================
     2→// 🔮 Phase 6: Predictive Self-Healing - Pattern Recognition (Week 1, Day 1-2)
     3→// 과거 복구 패턴 자동 인식 & 분류
     4→// ============================================================================
     5→
     6→// ============================================================================
     7→// RecoveryPattern: 복구 패턴 정의
     8→// ============================================================================
     9→
    10→struct RecoveryPattern {
    11→    pattern_id: u32,
    12→    pattern_type: String,           // "MemoryLeak", "IOBottleneck", etc.
    13→    confidence: f64,                // 0.0-1.0 (신뢰도)
    14→    timestamp: u64,                 // 패턴 감지 시간
    15→    duration_ms: u32,               // 지속 시간
    16→    recovery_time_ms: u32,          // 복구 소요 시간
    17→    success_rate: f64,              // 0.0-1.0 (과거 성공률)
    18→    frequency: u32,                 // 과거 발생 횟수
    19→    last_occurrence: u64,           // 마지막 발생 시간
    20→}
    21→
    22→impl RecoveryPattern {
    23→    fn new(pattern_type: String) -> RecoveryPattern {
    24→        RecoveryPattern {
    25→            pattern_id: 0,
    26→            pattern_type,
    27→            confidence: 0.0,
    28→            timestamp: 0,
    29→            duration_ms: 0,
    30→            recovery_time_ms: 0,
    31→            success_rate: 0.0,
    32→            frequency: 0,
    33→            last_occurrence: 0,
    34→        }
    35→    }
    36→
    37→    fn update_confidence(&mut self, new_evidence: f64) {
    38→        // 베이지안 업데이트: 새로운 증거로 신뢰도 갱신
    39→        // confidence = (confidence + new_evidence) / 2.0 (단순화)
    40→        self.confidence = ((self.confidence * (self.frequency as f64)) + new_evidence)
    41→            / ((self.frequency as f64) + 1.0);
    42→    }
    43→
    44→    fn increment_frequency(&mut self, timestamp: u64) {
    45→        self.frequency += 1;
    46→        self.last_occurrence = timestamp;
    47→    }
    48→
    49→    fn is_reliable(&self) -> bool {
    50→        // 신뢰할 수 있는 패턴: 신뢰도 >70% AND 발생 >3회
    51→        self.confidence > 0.70 && self.frequency > 3
    52→    }
    53→}
    54→
    55→// ============================================================================
    56→// PatternType: 6가지 인식 가능한 패턴
    57→// ============================================================================
    58→
    59→enum PatternType {
    60→    MemoryLeak,          // 포화도 지속 상승 (>5%/min)
    61→    IOBottleneck,        // I/O ops >50k/sec + Memory 증가
    62→    ThreadContention,    // Context switches >5M/sec + CPU >80%
    63→    PeriodicLoad,        // 시간 기반 주기적 부하
    64→    CacheThreshing,      // Cache miss >30% + Memory >80%
    65→    CombinedPressure,    // 3+ 압박 동시 발생
    66→}
    67→
    68→impl PatternType {
    69→    fn from_string(s: &str) -> PatternType {
    70→        match s {
    71→            "MemoryLeak" => PatternType::MemoryLeak,
    72→            "IOBottleneck" => PatternType::IOBottleneck,
    73→            "ThreadContention" => PatternType::ThreadContention,
    74→            "PeriodicLoad" => PatternType::PeriodicLoad,
    75→            "CacheThreshing" => PatternType::CacheThreshing,
    76→            "CombinedPressure" => PatternType::CombinedPressure,
    77→            _ => PatternType::CombinedPressure,
    78→        }
    79→    }
    80→
    81→    fn to_string(&self) -> String {
    82→        match self {
    83→            PatternType::MemoryLeak => "MemoryLeak".to_string(),
    84→            PatternType::IOBottleneck => "IOBottleneck".to_string(),
    85→            PatternType::ThreadContention => "ThreadContention".to_string(),
    86→            PatternType::PeriodicLoad => "PeriodicLoad".to_string(),
    87→            PatternType::CacheThreshing => "CacheThreshing".to_string(),
    88→            PatternType::CombinedPressure => "CombinedPressure".to_string(),
    89→        }
    90→    }
    91→
    92→    fn description(&self) -> String {
    93→        match self {
    94→            PatternType::MemoryLeak => "지속적 메모리 상승 (포화도 >5%/min)".to_string(),
    95→            PatternType::IOBottleneck => "I/O 병목 (ops >50k/sec)".to_string(),
    96→            PatternType::ThreadContention => "스레드 경합 (CS >5M/sec)".to_string(),
    97→            PatternType::PeriodicLoad => "주기적 부하 (시간 기반 반복)".to_string(),
    98→            PatternType::CacheThreshing => "캐시 쓰레싱 (miss >30%)".to_string(),
    99→            PatternType::CombinedPressure => "복합 압박 (3+ 동시)".to_string(),
   100→        }
   101→    }
   102→}
   103→
   104→// ============================================================================
   105→// PatternMatcher: 패턴 인식 엔진
   106→// ============================================================================
   107→
   108→struct PatternMatcher {
   109→    patterns: Vec<RecoveryPattern>,
   110→    max_patterns: usize,
   111→}
   112→
   113→impl PatternMatcher {
   114→    fn new() -> PatternMatcher {
   115→        PatternMatcher {
   116→            patterns: Vec::new(),
   117→            max_patterns: 1000,  // 최근 1000개 패턴 유지
   118→        }
   119→    }
   120→
   121→    // ========================================================================
   122→    // Pattern 1: Memory Leak Detection
   123→    // ========================================================================
   124→
   125→    fn detect_memory_leak(
   126→        &mut self,
   127→        saturation_history: &Vec<f64>,
   128→        timestamp: u64
   129→    ) -> Option<RecoveryPattern> {
   130→        if saturation_history.len() < 5 {
   131→            return None;
   132→        }
   133→
   134→        let recent = saturation_history.len();
   135→        let early = saturation_history[recent - 5];
   136→        let latest = saturation_history[recent - 1];
   137→
   138→        // 포화도 증가율 계산
   139→        let increase_rate = (latest - early) / 5.0;  // per sample
   140→
   141→        // 메모리 누수 신호: 지속적 상승 >1%/sample
   142→        if increase_rate > 0.01 {
   143→            let mut pattern = RecoveryPattern::new("MemoryLeak".to_string());
   144→            pattern.confidence = (increase_rate * 100.0).min(1.0);  // Normalize
   145→            pattern.timestamp = timestamp;
   146→            pattern.frequency = 1;
   147→            pattern.last_occurrence = timestamp;
   148→
   149→            self.add_pattern(pattern.clone());
   150→            return Some(pattern);
   151→        }
   152→
   153→        None
   154→    }
   155→
   156→    // ========================================================================
   157→    // Pattern 2: I/O Bottleneck Detection
   158→    // ========================================================================
   159→
   160→    fn detect_io_bottleneck(
   161→        &mut self,
   162→        io_ops: u64,
   163→        memory_saturation: f64,
   164→        timestamp: u64
   165→    ) -> Option<RecoveryPattern> {
   166→        // I/O ops >50k/sec AND Memory >80%
   167→        if io_ops > 50000 && memory_saturation > 0.80 {
   168→            let mut pattern = RecoveryPattern::new("IOBottleneck".to_string());
   169→
   170→            // 신뢰도: I/O 강도와 메모리 상관계수
   171→            let io_factor = (io_ops as f64 / 100000.0).min(1.0);  // Normalize
   172→            let mem_factor = (memory_saturation - 0.80) / 0.20;    // 80-100% range
   173→            pattern.confidence = ((io_factor + mem_factor) / 2.0).min(1.0);
   174→
   175→            pattern.timestamp = timestamp;
   176→            pattern.frequency = 1;
   177→            pattern.last_occurrence = timestamp;
   178→
   179→            self.add_pattern(pattern.clone());
   180→            return Some(pattern);
   181→        }
   182→
   183→        None
   184→    }
   185→
   186→    // ========================================================================
   187→    // Pattern 3: Thread Contention Detection
   188→    // ========================================================================
   189→
   190→    fn detect_thread_contention(
   191→        &mut self,
   192→        context_switches: u64,
   193→        cpu_utilization: f64,
   194→        timestamp: u64
   195→    ) -> Option<RecoveryPattern> {
   196→        // Context switches >5M/sec AND CPU >80%
   197→        if context_switches > 5_000_000 && cpu_utilization > 0.80 {
   198→            let mut pattern = RecoveryPattern::new("ThreadContention".to_string());
   199→
   200→            let cs_factor = (context_switches as f64 / 10_000_000.0).min(1.0);
   201→            let cpu_factor = (cpu_utilization - 0.80) / 0.20;
   202→            pattern.confidence = ((cs_factor + cpu_factor) / 2.0).min(1.0);
   203→
   204→            pattern.timestamp = timestamp;
   205→            pattern.frequency = 1;
   206→            pattern.last_occurrence = timestamp;
   207→
   208→            self.add_pattern(pattern.clone());
   209→            return Some(pattern);
   210→        }
   211→
   212→        None
   213→    }
   214→
   215→    // ========================================================================
   216→    // Pattern 4: Periodic Load Detection
   217→    // ========================================================================
   218→
   219→    fn detect_periodic_load(
   220→        &mut self,
   221→        hour_of_day: u32,
   222→        memory_saturation: f64,
   223→        past_occurrences: u32,
   224→        timestamp: u64
   225→    ) -> Option<RecoveryPattern> {
   226→        // 시간 기반 주기성 확인
   227→        // 같은 시간대에 반복적으로 높은 포화도 발생
   228→        if memory_saturation > 0.75 && past_occurrences > 5 {
   229→            let mut pattern = RecoveryPattern::new("PeriodicLoad".to_string());
   230→
   231→            // 신뢰도: 과거 발생 횟수
   232→            pattern.confidence = (past_occurrences as f64 / 20.0).min(1.0);
   233→
   234→            pattern.timestamp = timestamp;
   235→            pattern.frequency = past_occurrences;
   236→            pattern.last_occurrence = timestamp;
   237→
   238→            self.add_pattern(pattern.clone());
   239→            return Some(pattern);
   240→        }
   241→
   242→        None
   243→    }
   244→
   245→    // ========================================================================
   246→    // Pattern 5: Cache Thrashing Detection
   247→    // ========================================================================
   248→
   249→    fn detect_cache_thrashing(
   250→        &mut self,
   251→        page_faults: u64,
   252→        memory_saturation: f64,
   253→        timestamp: u64
   254→    ) -> Option<RecoveryPattern> {
   255→        // Cache miss rate (page faults) >30% + Memory >80%
   256→        let estimated_miss_rate = (page_faults as f64) / 1000.0;  // Normalize
   257→
   258→        if estimated_miss_rate > 0.30 && memory_saturation > 0.80 {
   259→            let mut pattern = RecoveryPattern::new("CacheThreshing".to_string());
   260→
   261→            pattern.confidence = ((estimated_miss_rate + memory_saturation) / 2.0).min(1.0);
   262→            pattern.timestamp = timestamp;
   263→            pattern.frequency = 1;
   264→            pattern.last_occurrence = timestamp;
   265→
   266→            self.add_pattern(pattern.clone());
   267→            return Some(pattern);
   268→        }
   269→
   270→        None
   271→    }
   272→
   273→    // ========================================================================
   274→    // Pattern 6: Combined Pressure Detection
   275→    // ========================================================================
   276→
   277→    fn detect_combined_pressure(
   278→        &mut self,
   279→        memory_saturation: f64,
   280→        cpu_utilization: f64,
   281→        io_ops: u64,
   282→        context_switches: u64,
   283→        timestamp: u64
   284→    ) -> Option<RecoveryPattern> {
   285→        // 3개 이상의 압박 동시 발생
   286→        let mut high_metric_count = 0;
   287→
   288→        if memory_saturation > 0.85 { high_metric_count += 1; }
   289→        if cpu_utilization > 0.85 { high_metric_count += 1; }
   290→        if io_ops > 30000 { high_metric_count += 1; }
   291→        if context_switches > 3_000_000 { high_metric_count += 1; }
   292→
   293→        if high_metric_count >= 3 {
   294→            let mut pattern = RecoveryPattern::new("CombinedPressure".to_string());
   295→
   296→            // 신뢰도: 높은 메트릭 개수
   297→            pattern.confidence = ((high_metric_count as f64) / 4.0).min(1.0);
   298→            pattern.timestamp = timestamp;
   299→            pattern.frequency = 1;
   300→            pattern.last_occurrence = timestamp;
   301→
   302→            self.add_pattern(pattern.clone());
   303→            return Some(pattern);
   304→        }
   305→
   306→        None
   307→    }
   308→
   309→    // ========================================================================
   310→    // 헬퍼 메서드
   311→    // ========================================================================
   312→
   313→    fn add_pattern(&mut self, pattern: RecoveryPattern) {
   314→        self.patterns.push(pattern);
   315→
   316→        // 최근 패턴만 유지
   317→        if self.patterns.len() > self.max_patterns {
   318→            self.patterns.remove(0);
   319→        }
   320→    }
   321→
   322→    fn find_pattern(&self, pattern_type: &str) -> Option<&RecoveryPattern> {
   323→        for pattern in &self.patterns {
   324→            if pattern.pattern_type == pattern_type {
   325→                return Some(pattern);
   326→            }
   327→        }
   328→        None
   329→    }
   330→
   331→    fn get_reliability_score(&self, pattern_type: &str) -> f64 {
   332→        match self.find_pattern(pattern_type) {
   333→            Some(pattern) => {
   334→                if pattern.is_reliable() {
   335→                    pattern.success_rate
   336→                } else {
   337→                    0.0
   338→                }
   339→            },
   340→            None => 0.0,
   341→        }
   342→    }
   343→
   344→    fn get_pattern_history_count(&self, pattern_type: &str) -> u32 {
   345→        let mut count = 0;
   346→        for pattern in &self.patterns {
   347→            if pattern.pattern_type == pattern_type {
   348→                count += 1;
   349→            }
   350→        }
   351→        count
   352→    }
   353→
   354→    fn predict_next_occurrence(&self, pattern_type: &str) -> Option<u64> {
   355→        if let Some(pattern) = self.find_pattern(pattern_type) {
   356→            // 단순화: 마지막 발생 시간 + 평균 주기
   357→            let avg_interval = 3600000;  // 1시간 (밀리초)
   358→            Some(pattern.last_occurrence + avg_interval)
   359→        } else {
   360→            None
   361→        }
   362→    }
   363→}
   364→
   365→// ============================================================================
   366→// ProbabilityCalculator: 확률 계산 엔진
   367→// ============================================================================
   368→
   369→struct ProbabilityCalculator {
   370→    threshold_confidence: f64,  // 0.7 (70% 이상만 신뢰)
   371→}
   372→
   373→impl ProbabilityCalculator {
   374→    fn new() -> ProbabilityCalculator {
   375→        ProbabilityCalculator {
   376→            threshold_confidence: 0.70,
   377→        }
   378→    }
   379→
   380→    fn calculate_pattern_probability(
   381→        &self,
   382→        pattern: &RecoveryPattern
   383→    ) -> f64 {
   384→        // 확률 = Confidence × Success_rate × Frequency_factor
   385→        let frequency_factor = ((pattern.frequency as f64) / 10.0).min(1.0);
   386→        let probability = pattern.confidence * pattern.success_rate * frequency_factor;
   387→        probability
   388→    }
   389→
   390→    fn is_pattern_actionable(&self, pattern: &RecoveryPattern) -> bool {
   391→        // 신뢰도가 임계값 이상이고 성공률이 높으면 행동 가능
   392→        pattern.confidence > self.threshold_confidence &&
   393→        pattern.success_rate > 0.60 &&
   394→        pattern.frequency > 2
   395→    }
   396→
   397→    fn rank_patterns(
   398→        &self,
   399→        patterns: &Vec<RecoveryPattern>
   400→    ) -> Vec<&RecoveryPattern> {
   401→        let mut ranked = patterns.iter().collect::<Vec<_>>();
   402→
   403→        // 신뢰도로 정렬
   404→        ranked.sort_by(|a, b| {
   405→            let prob_a = self.calculate_pattern_probability(a);
   406→            let prob_b = self.calculate_pattern_probability(b);
   407→            prob_b.partial_cmp(&prob_a).unwrap()
   408→        });
   409→
   410→        ranked
   411→    }
   412→}
