    77→// ============================================================================
    78→// PatternLearningState: 각 패턴별 학습 상태 추적
    79→// ============================================================================
    80→
    81→struct PatternLearningState {
    82→    pattern_id: u32,
    83→    pattern_type: String,
    84→    current_state: String,              // LearningState를 문자열로 저장
    85→    frequency: u32,                     // 발생 횟수
    86→    confidence: f64,                    // 현재 신뢰도 (0.0-1.0)
    87→    last_transition_time: u64,          // 마지막 상태 전이 시간
    88→    total_observations: u32,            // 누적 관찰 수
    89→    successful_predictions: u32,        // 성공한 예측 수
    90→    failed_predictions: u32,            // 실패한 예측 수
    91→    prediction_accuracy: f64,           // 예측 정확도 (0.0-1.0)
    92→    state_entry_time: u64,              // 현재 상태 진입 시간
    93→    time_in_state_ms: u32,              // 현재 상태 소요 시간 (ms)
    94→}
    95→
    96→impl PatternLearningState {
    97→    fn new(pattern_id: u32, pattern_type: String) -> PatternLearningState {
    98→        PatternLearningState {
    99→            pattern_id,
   100→            pattern_type,
   101→            current_state: "NoData".to_string(),
   102→            frequency: 0,
   103→            confidence: 0.0,
   104→            last_transition_time: 0,
   105→            total_observations: 0,
   106→            successful_predictions: 0,
   107→            failed_predictions: 0,
   108→            prediction_accuracy: 0.0,
   109→            state_entry_time: 0,
   110→            time_in_state_ms: 0,
   111→        }
   112→    }
   113→
   114→    fn observe(&mut self, timestamp: u64, evidence_confidence: f64) {
   115→        // 새로운 관찰 데이터 기록
   116→        self.total_observations += 1;
   117→        self.frequency += 1;
   118→
   119→        // 베이지안 신뢰도 갱신
   120→        let weight = (self.frequency as f64) / ((self.frequency as f64) + 1.0);
   121→        self.confidence = self.confidence * weight + evidence_confidence * (1.0 - weight);
   122→
   123→        // 신뢰도를 0.0-1.0 범위로 제한
   124→        if self.confidence > 1.0 {
   125→            self.confidence = 1.0;
   126→        }
   127→        if self.confidence < 0.0 {
   128→            self.confidence = 0.0;
   129→        }
   130→    }
   131→
   132→    fn try_transition(&mut self, timestamp: u64) -> bool {
   133→        // 상태 전이 시도: frequency 기반으로 다음 상태로 진행 가능한지 확인
   134→        let old_state = self.current_state.clone();
   135→        let new_state = self.calculate_next_state();
   136→
   137→        if new_state != old_state {
   138→            self.current_state = new_state.clone();
   139→            self.last_transition_time = timestamp;
   140→            self.state_entry_time = timestamp;
   141→            return true;
   142→        }
   143→        false
   144→    }
   145→
   146→    fn calculate_next_state(&self) -> String {
   147→        // frequency 기반 상태 결정
   148→        match self.frequency {
   149→            0 => "NoData".to_string(),
   150→            1..=3 => "Observing".to_string(),
   151→            4..=9 => "Emerging".to_string(),
   152→            10..=29 => "Established".to_string(),
   153→            30..=u32::MAX => "Mature".to_string(),
   154→        }
   155→    }
   156→
   157→    fn update_state_time(&mut self, current_timestamp: u64) {
   158→        // 현재 상태 소요 시간 업데이트
   159→        if self.state_entry_time > 0 {
   160→            self.time_in_state_ms = (current_timestamp - self.state_entry_time) as u32;
   161→        }
   162→    }
   163→
   164→    fn record_prediction_result(&mut self, success: bool) {
   165→        // 예측 결과 기록
   166→        if success {
   167→            self.successful_predictions += 1;
   168→        } else {
   169→            self.failed_predictions += 1;
   170→        }
   171→
   172→        // 예측 정확도 계산
   173→        let total = self.successful_predictions + self.failed_predictions;
   174→        if total > 0 {
   175→            self.prediction_accuracy =
   176→                (self.successful_predictions as f64) / (total as f64);
   177→        }
   178→    }
   179→
   180→    fn is_actionable(&self) -> bool {
   181→        // 이 패턴으로 조치를 취할 수 있는가?
   182→        // 요구사항:
   183→        // 1. Emerging 상태 이상 (confidence >50%)
   184→        // 2. 최소 4회 관찰 (frequency >=4)
   185→        // 3. 예측 정확도 >60% (또는 아직 예측 없음)
   186→        self.frequency >= 4 &&
   187→        self.confidence > 0.5 &&
   188→        (self.successful_predictions + self.failed_predictions == 0 ||
   189→         self.prediction_accuracy > 0.6)
   190→    }
   191→
   192→    fn get_action_confidence(&self) -> f64 {
   193→        // 조치를 취할 때의 신뢰도 (0.0-1.0)
   194→        // = (상태 기반 actionability) × (신뢰도) × (예측 정확도 또는 1.0)
   195→        let state_actionability = match self.current_state.as_str() {
   196→            "NoData" => 0.0,
   197→            "Observing" => 0.2,
   198→            "Emerging" => 0.5,
   199→            "Established" => 0.8,
   200→            "Mature" => 1.0,
   201→            _ => 0.0,
   202→        };
   203→
   204→        let accuracy_factor = if self.successful_predictions + self.failed_predictions > 0 {
   205→            self.prediction_accuracy
   206→        } else {
   207→            1.0  // 예측 기록이 없으면 신뢰도만 사용
   208→        };
   209→
   210→        state_actionability * self.confidence * accuracy_factor
   211→    }
   212→}
   213→
   214→// ============================================================================
   215→// StateTransitionLog: 상태 전이 로그
   216→// ============================================================================
   217→
   218→struct StateTransition {
   219→    pattern_id: u32,
   220→    timestamp: u64,
   221→    from_state: String,
   222→    to_state: String,
   223→    frequency_at_transition: u32,
   224→    confidence_at_transition: f64,
   225→    reason: String,
   226→}
   227→
   228→impl StateTransition {
   229→    fn new(
   230→        pattern_id: u32,
   231→        timestamp: u64,
   232→        from_state: String,
   233→        to_state: String,
   234→        frequency: u32,
   235→        confidence: f64,
   236→        reason: String,
   237→    ) -> StateTransition {
   238→        StateTransition {
   239→            pattern_id,
   240→            timestamp,
   241→            from_state,
   242→            to_state,
   243→            frequency_at_transition: frequency,
   244→            confidence_at_transition: confidence,
   245→            reason,
   246→        }
   247→    }
   248→}
