   289→// ============================================================================
   290→// PatternStatistics: 패턴 통계
   291→// ============================================================================
   292→
   293→struct PatternStatistics {
   294→    pattern_type: String,
   295→    total_occurrences: usize,
   296→    success_count: usize,
   297→    failure_count: usize,
   298→    success_rate: f64,
   299→    average_recovery_time_ms: u32,
   300→    average_improvement_ratio: f64,
   301→    min_recovery_time_ms: u32,
   302→    max_recovery_time_ms: u32,
   303→    last_occurrence_timestamp: u64,
   304→}
