     2→// 🔮 Phase 6: Predictive Self-Healing - Predictor Module (Week 2, Day 8-10)
     3→// 학습된 패턴으로 미래 상태 예측 & 위기 발생 시간 예측
     4→// ============================================================================
     5→
     6→// ============================================================================
     7→// TrendType: 추세 분류
     8→// ============================================================================
     9→
    10→enum TrendType {
    11→    Stable,          // 안정적 (변화 <2%/sample)
    12→    Rising,          // 상승 추세 (증가율 >2%/sample)
    13→    Falling,         // 하강 추세 (감소율 >2%/sample)
    14→    Oscillating,     // 진동 (표준편차 높음)
    15→}
    16→
    17→impl TrendType {
    18→    fn to_string(&self) -> String {
    19→        match self {
    20→            TrendType::Stable => "Stable".to_string(),
    21→            TrendType::Rising => "Rising".to_string(),
    22→            TrendType::Falling => "Falling".to_string(),
    23→            TrendType::Oscillating => "Oscillating".to_string(),
    24→        }
    25→    }
    26→}
    27→
    28→// ============================================================================
    29→// TimeSeriesData: 시계열 데이터
    30→// ============================================================================
    31→
    32→struct TimeSeriesData {
    33→    timestamps: Vec<u64>,
    34→    values: Vec<f64>,
    35→    max_size: usize,         // 최대 윈도우 크기 (기본 100)
    36→}
    37→
    38→impl TimeSeriesData {
    39→    fn new() -> TimeSeriesData {
    40→        TimeSeriesData {
    41→            timestamps: Vec::new(),
    42→            values: Vec::new(),
    43→            max_size: 100,
    44→        }
    45→    }
    46→
    47→    fn add_sample(&mut self, timestamp: u64, value: f64) {
    48→        self.timestamps.push(timestamp);
    49→        self.values.push(value);
    50→
    51→        // 윈도우 크기 초과 시 가장 오래된 항목 제거
    52→        if self.values.len() > self.max_size {
    53→            self.timestamps.remove(0);
    54→            self.values.remove(0);
    55→        }
    56→    }
    57→
    58→    fn len(&self) -> usize {
    59→        self.values.len()
    60→    }
    61→
    62→    fn is_empty(&self) -> bool {
    63→        self.values.is_empty()
    64→    }
    65→
    66→    fn get_mean(&self) -> f64 {
    67→        if self.values.is_empty() {
    68→            return 0.0;
    69→        }
    70→        let sum: f64 = self.values.iter().sum();
    71→        sum / self.values.len() as f64
    72→    }
    73→
    74→    fn get_std_dev(&self) -> f64 {
    75→        if self.values.len() < 2 {
    76→            return 0.0;
    77→        }
    78→        let mean = self.get_mean();
    79→        let variance: f64 = self.values
    80→            .iter()
    81→            .map(|v| (v - mean).powi(2))
    82→            .sum::<f64>()
    83→            / (self.values.len() - 1) as f64;
    84→        variance.sqrt()
    85→    }
    86→
    87→    fn get_trend_type(&self) -> TrendType {
    88→        if self.values.len() < 3 {
    89→            return TrendType::Stable;
    90→        }
    91→
    92→        // 최근 3개 샘플로 추세 분석
    93→        let recent_values = &self.values[self.values.len() - 3..];
    94→        let diff1 = recent_values[1] - recent_values[0];
    95→        let diff2 = recent_values[2] - recent_values[1];
    96→        let avg_change = (diff1 + diff2) / 2.0;
    97→        let mean = self.get_mean();
    98→
    99→        if mean > 0.0 {
   100→            let change_rate = avg_change / mean;
   101→            if change_rate > 0.02 {
   102→                return TrendType::Rising;
   103→            } else if change_rate < -0.02 {
   104→                return TrendType::Falling;
   105→            }
   106→        }
   107→
   108→        let std_dev = self.get_std_dev();
   109→        if std_dev > mean * 0.3 {
   110→            return TrendType::Oscillating;
   111→        }
   112→
   113→        TrendType::Stable
   114→    }
   115→}
