   117→// ============================================================================
   118→// PolynomialModel: 다항 회귀 모델
   119→// ============================================================================
   120→
   121→struct PolynomialModel {
   122→    degree: u32,            // 1=선형, 2=이차, 3=삼차
   123→    coefficients: Vec<f64>, // 최대 4개 (0차-3차 항)
   124→    r_squared: f64,         // 결정계수 (0.0-1.0)
   125→    rmse: f64,              // 제곱근 평균 오차
   126→}
   127→
   128→impl PolynomialModel {
   129→    fn new(degree: u32) -> PolynomialModel {
   130→        PolynomialModel {
   131→            degree: degree.min(3),
   132→            coefficients: vec![0.0; (degree.min(3) + 1) as usize],
   133→            r_squared: 0.0,
   134→            rmse: 0.0,
   135→        }
   136→    }
   137→
   138→    fn fit(&mut self, x_data: &[f64], y_data: &[f64]) -> bool {
   139→        // 최소 degree+1개 데이터 필요
   140→        if x_data.len() < (self.degree + 1) as usize || x_data.len() != y_data.len() {
   141→            return false;
   142→        }
   143→
   144→        // 간단한 선형 회귀 구현 (1차만 지원)
   145→        if self.degree == 1 {
   146→            return self.fit_linear(x_data, y_data);
   147→        }
   148→
   149→        // 2차/3차는 근사화 (간단한 구현)
   150→        if self.degree == 2 || self.degree == 3 {
   151→            return self.fit_polynomial_approx(x_data, y_data);
   152→        }
   153→
   154→        false
   155→    }
   156→
   157→    fn fit_linear(&mut self, x_data: &[f64], y_data: &[f64]) -> bool {
   158→        let n = x_data.len() as f64;
   159→        let mean_x = x_data.iter().sum::<f64>() / n;
   160→        let mean_y = y_data.iter().sum::<f64>() / n;
   161→
   162→        let mut numerator = 0.0;
   163→        let mut denominator = 0.0;
   164→
   165→        for i in 0..x_data.len() {
   166→            numerator += (x_data[i] - mean_x) * (y_data[i] - mean_y);
   167→            denominator += (x_data[i] - mean_x).powi(2);
   168→        }
   169→
   170→        if denominator == 0.0 {
   171→            return false;
   172→        }
   173→
   174→        let slope = numerator / denominator;
   175→        let intercept = mean_y - slope * mean_x;
   176→
   177→        self.coefficients[0] = intercept;
   178→        self.coefficients[1] = slope;
   179→
   180→        // R² 계산
   181→        let mut ss_res = 0.0;
   182→        let mut ss_tot = 0.0;
   183→        for i in 0..y_data.len() {
   184→            let predicted = intercept + slope * x_data[i];
   185→            ss_res += (y_data[i] - predicted).powi(2);
   186→            ss_tot += (y_data[i] - mean_y).powi(2);
   187→        }
   188→
   189→        if ss_tot > 0.0 {
   190→            self.r_squared = 1.0 - (ss_res / ss_tot);
   191→        }
   192→
   193→        self.rmse = (ss_res / n).sqrt();
   194→        true
   195→    }
   196→
   197→    fn fit_polynomial_approx(&mut self, x_data: &[f64], y_data: &[f64]) -> bool {
   198→        // 이차/삼차는 선형으로 근사 (간단한 구현)
   199→        self.fit_linear(x_data, y_data)
   200→    }
   201→
   202→    fn predict(&self, x: f64) -> f64 {
   203→        let mut result = 0.0;
   204→        let mut x_power = 1.0;
   205→
   206→        for i in 0..=self.degree.min(3) as usize {
   207→            result += self.coefficients[i] * x_power;
   208→            x_power *= x;
   209→        }
   210→
   211→        result
   212→    }
   213→
   214→    fn predict_with_error(&self, x: f64) -> (f64, f64) {
   215→        let prediction = self.predict(x);
   216→        let error_bound = self.rmse * 2.0; // 95% 신뢰 구간
   217→        (prediction, error_bound)
   218→    }
   219→}
