   232→impl TrendPredictor {
   233→    fn new() -> TrendPredictor {
   234→        TrendPredictor {
   235→            data: TimeSeriesData::new(),
   236→            model_linear: PolynomialModel::new(1),
   237→            model_quadratic: PolynomialModel::new(2),
   238→            last_prediction_accuracy: 0.0,
   239→        }
   240→    }
   241→
   242→    fn add_observation(&mut self, timestamp: u64, value: f64) {
   243→        self.data.add_sample(timestamp, value);
   244→
   245→        // 충분한 데이터가 있으면 모델 재학습
   246→        if self.data.len() >= 5 {
   247→            self.retrain_models();
   248→        }
   249→    }
   250→
   251→    fn retrain_models(&mut self) {
   252→        let n = self.data.len();
   253→        if n < 2 {
   254→            return;
   255→        }
   256→
   257→        // x 데이터를 정규화 (0부터 시작)
   258→        let mut x_normalized = Vec::new();
   259→        for i in 0..n {
   260→            x_normalized.push(i as f64);
   261→        }
   262→
   263→        // 선형 모델 학습
   264→        let _ = self.model_linear.fit(&x_normalized, &self.data.values);
   265→
   266→        // 이차 모델 학습
   267→        let _ = self.model_quadratic.fit(&x_normalized, &self.data.values);
   268→    }
   269→
   270→    fn predict_next_value(&self) -> (f64, f64) {
   271→        // 다음 샘플 예측 (선형 모델 사용)
   272→        let x_next = self.data.len() as f64;
   273→        self.model_linear.predict_with_error(x_next)
   274→    }
   275→
   276→    fn predict_value_at(&self, steps_ahead: u32) -> (f64, f64) {
   277→        // steps_ahead만큼 미래의 값 예측
   278→        let x_future = (self.data.len() as u32 + steps_ahead) as f64;
   279→        self.model_linear.predict_with_error(x_future)
   280→    }
   281→
   282→    fn get_trend_type(&self) -> TrendType {
   283→        self.data.get_trend_type()
   284→    }
   285→
   286→    fn get_forecast_quality(&self) -> f64 {
   287→        // R² 값을 품질로 반환 (0.0-1.0)
   288→        self.model_linear.r_squared
   289→    }
   290→}
