   292→// ============================================================================
   293→// TimeToEventPredictor: 특정 이벤트 발생 시간 예측
   294→// ============================================================================
   295→
   296→struct TimeToEventPredictor {
   297→    saturation_data: TimeSeriesData,
   298→    threshold: f64,                 // 위기 임계값 (기본 0.95)
   299→    estimated_time_to_event: u32,   // 예상 시간 (ms)
   300→    confidence: f64,                // 예측 신뢰도 (0.0-1.0)
   301→}
   302→
   303→impl TimeToEventPredictor {
   304→    fn new(threshold: f64) -> TimeToEventPredictor {
   305→        TimeToEventPredictor {
   306→            saturation_data: TimeSeriesData::new(),
   307→            threshold,
   308→            estimated_time_to_event: 0,
   309→            confidence: 0.0,
   310→        }
   311→    }
   312→
   313→    fn add_saturation_sample(&mut self, timestamp: u64, saturation: f64) {
   314→        self.saturation_data.add_sample(timestamp, saturation);
   315→
   316→        // 데이터가 충분하면 위기 발생 시간 예측
   317→        if self.saturation_data.len() >= 5 {
   318→            self.estimate_time_to_event();
   319→        }
   320→    }
   321→
   322→    fn estimate_time_to_event(&mut self) {
   323→        let n = self.saturation_data.len();
   324→        if n < 2 {
   325→            return;
   326→        }
   327→
   328→        // 최근 샘플들의 변화율 계산
   329→        let last_value = self.saturation_data.values[n - 1];
   330→        let prev_value = self.saturation_data.values[n - 2];
   331→        let change_rate = last_value - prev_value;
   332→
   333→        // 현재 포화도에서 임계값까지 필요한 시간 추정
   334→        if change_rate > 0.0 {
   335→            let remaining = self.threshold - last_value;
   336→            if remaining > 0.0 {
   337→                // 100ms 샘플링 기준
   338→                let estimated_samples = remaining / change_rate;
   339→                self.estimated_time_to_event = (estimated_samples * 100.0) as u32;
   340→
   341→                // 신뢰도 계산 (변화율 일관성 기반)
   342→                if n >= 3 {
   343→                    let prev_change = self.saturation_data.values[n - 2] - self.saturation_data.values[n - 3];
   344→                    let consistency = 1.0 - (change_rate - prev_change).abs() / change_rate.max(0.001);
   345→                    self.confidence = consistency.max(0.3).min(1.0);
   346→                } else {
   347→                    self.confidence = 0.5;
   348→                }
   349→            } else {
   350→                // 이미 임계값 초과
   351→                self.estimated_time_to_event = 0;
   352→                self.confidence = 1.0;
   353→            }
   354→        } else {
   355→            // 감소 중: 위기 발생 예상 안 함
   356→            self.estimated_time_to_event = u32::MAX;
   357→            self.confidence = 1.0;
   358→        }
   359→    }
   360→
   361→    fn get_time_to_event(&self) -> Option<u32> {
   362→        if self.estimated_time_to_event == u32::MAX {
   363→            None
   364→        } else if self.estimated_time_to_event > 0 {
   365→            Some(self.estimated_time_to_event)
   366→        } else {
   367→            Some(0)  // 이미 임계값 초과
   368→        }
   369→    }
   370→
   371→    fn get_prediction_confidence(&self) -> f64 {
   372→        self.confidence
   373→    }
   374→}
