   376→// ============================================================================
   377→// ForecastAccuracy: 예측 정확도 평가
   378→// ============================================================================
   379→
   380→struct ForecastAccuracy {
   381→    predictions: Vec<(f64, f64)>,  // (예측값, 실제값)
   382→    errors: Vec<f64>,
   383→    mae: f64,                       // 평균 절대 오차
   384→    rmse: f64,                      // 제곱근 평균 제곱 오차
   385→    mape: f64,                      // 평균 절대 백분율 오차
   386→    accuracy_percentage: f64,       // ±5% 이내 정확도 (%)
   387→}
   388→
   389→impl ForecastAccuracy {
   390→    fn new() -> ForecastAccuracy {
   391→        ForecastAccuracy {
   392→            predictions: Vec::new(),
   393→            errors: Vec::new(),
   394→            mae: 0.0,
   395→            rmse: 0.0,
   396→            mape: 0.0,
   397→            accuracy_percentage: 0.0,
   398→        }
   399→    }
   400→
   401→    fn record_prediction(&mut self, predicted: f64, actual: f64) {
   402→        self.predictions.push((predicted, actual));
   403→        let error = actual - predicted;
   404→        self.errors.push(error);
   405→
   406→        self.update_metrics();
   407→    }
   408→
   409→    fn update_metrics(&mut self) {
   410→        if self.predictions.is_empty() {
   411→            return;
   412→        }
   413→
   414→        let n = self.predictions.len() as f64;
   415→
   416→        // MAE (평균 절대 오차)
   417→        self.mae = self.errors.iter().map(|e| e.abs()).sum::<f64>() / n;
   418→
   419→        // RMSE (제곱근 평균 제곱 오차)
   420→        let mse = self.errors.iter().map(|e| e.powi(2)).sum::<f64>() / n;
   421→        self.rmse = mse.sqrt();
   422→
   423→        // MAPE (평균 절대 백분율 오차)
   424→        let mut mape_sum = 0.0;
   425→        for (pred, actual) in &self.predictions {
   426→            if actual.abs() > 0.0001 {
   427→                mape_sum += ((actual - pred).abs() / actual.abs());
   428→            }
   429→        }
   430→        self.mape = (mape_sum / n) * 100.0;
   431→
   432→        // ±5% 이내 정확도
   433→        let within_5_percent = self.predictions
   434→            .iter()
   435→            .filter(|(pred, actual)| {
   436→                if actual.abs() > 0.0001 {
   437→                    let error_percent = ((actual - pred).abs() / actual.abs()) * 100.0;
   438→                    error_percent <= 5.0
   439→                } else {
   440→                    (pred - actual).abs() <= 0.05
   441→                }
   442→            })
   443→            .count();
   444→        self.accuracy_percentage = (within_5_percent as f64 / n) * 100.0;
   445→    }
   446→
   447→    fn get_summary(&self) -> String {
   448→        format!(
   449→            "MAE: {:.4}, RMSE: {:.4}, MAPE: {:.2}%, Accuracy(±5%): {:.1}%",
   450→            self.mae, self.rmse, self.mape, self.accuracy_percentage
   451→        )
   452→    }
   453→}
