    70→    fn minimum_confidence(&self) -> f64 {
    71→        // 각 조치를 실행하기 위한 최소 신뢰도
    72→        match self {
    73→            ProactiveAction::AggressiveGC => 0.70,
    74→            ProactiveAction::CachePreemption => 0.75,
    75→            ProactiveAction::ThreadPoolAdjustment => 0.70,
    76→            ProactiveAction::BufferPoolExpansion => 0.80,
    77→            ProactiveAction::CPUAffinity => 0.65,
    78→            ProactiveAction::NetworkPreparation => 0.75,
    79→            ProactiveAction::SlowQueryCaching => 0.70,
    80→            ProactiveAction::ConnectionPooling => 0.75,
    81→            ProactiveAction::GracefulDegradationPreload => 0.85,
    82→            ProactiveAction::EmergencyShutdownPrep => 0.90,
    83→        }
    84→    }
    85→}
    86→
    87→// ============================================================================
    88→// ScheduledAction: 스케줄된 조치
    89→// ============================================================================
    90→
    91→struct ScheduledAction {
    92→    action: String,              // ProactiveAction의 문자열 표현
    93→    scheduled_timestamp: u64,    // 예정된 실행 시간
    94→    executed: bool,
    95→    execution_timestamp: u64,
    96→    success: bool,
    97→    confidence: f64,
    98→    predicted_improvement: f64,
    99→}
   100→
   101→impl ScheduledAction {
   102→    fn new(
   103→        action_type: ProactiveAction,
   104→        scheduled_timestamp: u64,
   105→        confidence: f64,
   106→    ) -> ScheduledAction {
   107→        let (improvement, _) = action_type.impact_estimate();
   108→        ScheduledAction {
   109→            action: action_type.to_string(),
   110→            scheduled_timestamp,
   111→            executed: false,
   112→            execution_timestamp: 0,
   113→            success: false,
   114→            confidence,
   115→            predicted_improvement: improvement,
   116→        }
   117→    }
   118→
   119→    fn execute(&mut self, current_timestamp: u64) {
   120→        self.executed = true;
   121→        self.execution_timestamp = current_timestamp;
   122→        // success는 실제 복구 결과에 따라 나중에 설정됨
   123→    }
   124→
   125→    fn is_due(&self, current_timestamp: u64) -> bool {
   126→        !self.executed && current_timestamp >= self.scheduled_timestamp
   127→    }
   128→}
   129→
   130→// ============================================================================
   131→// ActionScheduler: 조치 스케줄러
   132→// ============================================================================
   133→
   134→struct ActionScheduler {
   135→    scheduled_actions: Vec<ScheduledAction>,
   136→    execution_queue: Vec<ScheduledAction>,
   137→    executed_count: u32,
   138→    success_count: u32,
   139→    failure_count: u32,
   140→}
   141→
   142→impl ActionScheduler {
   143→    fn new() -> ActionScheduler {
   144→        ActionScheduler {
   145→            scheduled_actions: Vec::new(),
   146→            execution_queue: Vec::new(),
   147→            executed_count: 0,
   148→            success_count: 0,
   149→            failure_count: 0,
   150→        }
   151→    }
   152→
   153→    fn schedule_action(
   154→        &mut self,
   155→        action_type: ProactiveAction,
   156→        scheduled_timestamp: u64,
   157→        confidence: f64,
   158→    ) -> bool {
   159→        // 신뢰도 확인
   160→        if confidence < action_type.minimum_confidence() {
   161→            return false;
   162→        }
   163→
   164→        let action = ScheduledAction::new(action_type, scheduled_timestamp, confidence);
   165→        self.scheduled_actions.push(action);
   166→        true
   167→    }
   168→
   169→    fn check_and_queue_due_actions(&mut self, current_timestamp: u64) {
   170→        for action in &mut self.scheduled_actions {
   171→            if action.is_due(current_timestamp) && !action.executed {
   172→                action.execute(current_timestamp);
   173→                self.execution_queue.push(action.clone());
   174→                self.executed_count += 1;
   175→            }
   176→        }
   177→    }
   178→
   179→    fn get_next_action(&mut self) -> Option<ScheduledAction> {
   180→        if self.execution_queue.is_empty() {
   181→            None
   182→        } else {
   183→            Some(self.execution_queue.remove(0))
   184→        }
   185→    }
   186→
   187→    fn record_action_result(&mut self, action: &ScheduledAction, success: bool) {
   188→        if success {
   189→            self.success_count += 1;
   190→        } else {
   191→            self.failure_count += 1;
   192→        }
   193→
   194→        // 실제 구현에서는 scheduled_actions 업데이트
   195→    }
   196→
   197→    fn get_pending_actions_count(&self) -> usize {
   198→        self.scheduled_actions
   199→            .iter()
   200→            .filter(|a| !a.executed)
   201→            .count()
   202→    }
   203→
   204→    fn get_success_ratio(&self) -> f64 {
   205→        let total = self.executed_count as f64;
   206→        if total == 0.0 {
   207→            return 0.0;
   208→        }
   209→        (self.success_count as f64) / total
   210→    }
   211→}
   212→
   213→// ============================================================================
   214→// SuccessRatioTracker: 조치별 성공률 추적
   215→// ============================================================================
   216→
   217→struct ActionSuccessRecord {
   218→    action_type: String,
   219→    total_attempts: u32,
   220→    successful_attempts: u32,
   221→    average_improvement: f64,
   222→    last_execution: u64,
   223→}
   224→
   225→struct SuccessRatioTracker {
   226→    records: Vec<ActionSuccessRecord>,
   227→}
   228→
   229→impl SuccessRatioTracker {
   230→    fn new() -> SuccessRatioTracker {
   231→        SuccessRatioTracker {
   232→            records: Vec::new(),
   233→        }
   234→    }
   235→
   236→    fn initialize_all_actions(&mut self) {
   237→        // 10가지 조치 모두 초기화
   238→        let action_names = vec![
   239→            "AggressiveGC",
   240→            "CachePreemption",
   241→            "ThreadPoolAdjustment",
   242→            "BufferPoolExpansion",
   243→            "CPUAffinity",
   244→            "NetworkPreparation",
   245→            "SlowQueryCaching",
   246→            "ConnectionPooling",
   247→            "GracefulDegradationPreload",
   248→            "EmergencyShutdownPrep",
   249→        ];
   250→
   251→        for name in action_names {
   252→            self.records.push(ActionSuccessRecord {
   253→                action_type: name.to_string(),
   254→                total_attempts: 0,
   255→                successful_attempts: 0,
   256→                average_improvement: 0.0,
   257→                last_execution: 0,
   258→            });
   259→        }
   260→    }
   261→
   262→    fn record_execution(&mut self, action_type: &str, success: bool, improvement: f64, timestamp: u64) {
   263→        for record in &mut self.records {
   264→            if record.action_type == action_type {
   265→                record.total_attempts += 1;
   266→                if success {
   267→                    record.successful_attempts += 1;
   268→                    record.average_improvement =
   269→                        (record.average_improvement * ((record.successful_attempts - 1) as f64)
   270→                            + improvement)
   271→                            / (record.successful_attempts as f64);
   272→                }
   273→                record.last_execution = timestamp;
   274→                return;
   275→            }
   276→        }
   277→    }
   278→
   279→    fn get_success_rate(&self, action_type: &str) -> f64 {
   280→        for record in &self.records {
   281→            if record.action_type == action_type {
   282→                if record.total_attempts == 0 {
   283→                    return 0.0;
   284→                }
   285→                return (record.successful_attempts as f64) / (record.total_attempts as f64);
   286→            }
   287→        }
   288→        0.0
   289→    }
   290→
   291→    fn get_average_improvement(&self, action_type: &str) -> f64 {
   292→        for record in &self.records {
   293→            if record.action_type == action_type {
   294→                return record.average_improvement;
   295→            }
   296→        }
   297→        0.0
   298→    }
   299→
   300→    fn get_best_action(&self) -> Option<String> {
   301→        // 성공률이 가장 높은 조치 반환
   302→        let mut best: Option<(String, f64)> = None;
   303→
   304→        for record in &self.records {
   305→            if record.total_attempts > 0 {
   306→                let success_rate =
   307→                    (record.successful_attempts as f64) / (record.total_attempts as f64);
   308→                match best {
   309→                    None => best = Some((record.action_type.clone(), success_rate)),
   310→                    Some((_, best_rate)) if success_rate > best_rate => {
   311→                        best = Some((record.action_type.clone(), success_rate));
   312→                    }
   313→                    _ => {}
   314→                }
   315→            }
   316→        }
   317→
   318→        best.map(|(action, _)| action)
   319→    }
   320→
   321→    fn get_summary(&self) -> String {
   322→        let mut summary = String::new();
   323→        for record in &self.records {
   324→            if record.total_attempts > 0 {
   325→                let success_rate =
   326→                    (record.successful_attempts as f64) / (record.total_attempts as f64) * 100.0;
   327→                summary.push_str(&format!(
   328→                    "{}: {}% ({}|{})\n",
   329→                    record.action_type, success_rate as u32, record.successful_attempts, record.total_attempts
   330→                ));
   331→            }
   332→        }
   333→        summary
   334→    }
   335→}
   336→
   337→// ============================================================================
   338→// ProactiveDispatcher: 통합 디스패처
   339→// ============================================================================
   340→
   341→struct ProactiveDispatcher {
   342→    scheduler: ActionScheduler,
   343→    tracker: SuccessRatioTracker,
   344→}
   345→
   346→impl ProactiveDispatcher {
   347→    fn new() -> ProactiveDispatcher {
   348→        let mut tracker = SuccessRatioTracker::new();
   349→        tracker.initialize_all_actions();
   350→
   351→        ProactiveDispatcher {
   352→            scheduler: ActionScheduler::new(),
   353→            tracker,
   354→        }
   355→    }
   356→
   357→    fn dispatch_action(
   358→        &mut self,
   359→        action_type: ProactiveAction,
   360→        scheduled_timestamp: u64,
   361→        confidence: f64,
   362→    ) -> bool {
   363→        self.scheduler.schedule_action(action_type, scheduled_timestamp, confidence)
   364→    }
   365→
   366→    fn process_due_actions(&mut self, current_timestamp: u64) {
   367→        self.scheduler.check_and_queue_due_actions(current_timestamp);
   368→    }
   369→
   370→    fn execute_next_action(&mut self) -> Option<String> {
   371→        match self.scheduler.get_next_action() {
   372→            Some(action) => {
   373→                // 실제 실행 로직 여기에 구현
   374→                Some(action.action.clone())
   375→            }
   376→            None => None,
   377→        }
   378→    }
   379→
   380→    fn record_action_outcome(&mut self, action_type: &str, success: bool, improvement: f64, timestamp: u64) {
   381→        self.tracker.record_execution(action_type, success, improvement, timestamp);
   382→    }
   383→
   384→    fn get_action_success_rate(&self, action_type: &str) -> f64 {
   385→        self.tracker.get_success_rate(action_type)
   386→    }
   387→
   388→    fn get_best_performing_action(&self) -> Option<String> {
   389→        self.tracker.get_best_action()
   390→    }
   391→
   392→    fn get_status(&self) -> String {
   393→        format!(
   394→            "Pending: {}, Success Ratio: {:.1}%\n{}",
   395→            self.scheduler.get_pending_actions_count(),
   396→            self.scheduler.get_success_ratio() * 100.0,
   397→            self.tracker.get_summary()
   398→        )
   399→    }
   400→}
