    64→impl SelfLearningPredictor {
    65→    pub fn new() -> SelfLearningPredictor {
    66→        SelfLearningPredictor {
    67→            pattern_states: Vec::new(),
    68→            pattern_statistics: Vec::new(),
    69→            trend_predictors: Vec::new(),
    70→            dispatcher: ProactiveDispatcher::new(),
    71→            min_confidence_for_action: 0.80,
    72→            min_confidence_for_preparation: 0.70,
    73→            predictions_made: 0,
    74→            actions_executed: 0,
    75→            successful_predictions: 0,
    76→        }
    77→    }
    78→
    79→    // ========================================================================
    80→    // 공개 API: 예측 & 조치 실행
    81→    // ========================================================================
    82→
    83→    /// 패턴 기반 예측 수행
    84→    pub fn predict_pattern(
    85→        &mut self,
    86→        pattern_id: u32,
    87→        pattern_type: String,
    88→        current_saturation: f64,
    89→    ) -> PredictionOutcome {
    90→        let mut outcome = PredictionOutcome::new(pattern_type.clone());
    91→
    92→        // Step 1: Week 1 데이터 조회
    93→        let current_confidence = self.get_pattern_confidence(pattern_id);
    94→        let stats = self.get_pattern_statistics(&pattern_type);
    95→        outcome.current_confidence = current_confidence;
    96→
    97→        // Step 2: Week 2 예측
    98→        let predictor = self.get_or_create_trend_predictor(pattern_id as usize);
    99→        let (next_saturation, _) = predictor.predict_next_value();
   100→        outcome.predicted_next_state = next_saturation;
   101→
   102→        // Step 3: 위기 시간 계산
   103→        if next_saturation > 0.90 {
   104→            outcome.time_to_critical = Some(self.estimate_time_to_critical(pattern_id, current_saturation));
   105→        }
   106→
   107→        // Step 4: 조치 추천
   108→        let improvement_potential = self.calculate_improvement_potential(&pattern_type, &stats);
   109→        outcome.recommended_actions =
   110→            self.select_proactive_actions(&pattern_type, current_confidence, improvement_potential);
   111→
   112→        // Step 5: 통합 신뢰도 계산
   113→        outcome.overall_confidence = self.calculate_integrated_confidence(
   114→            current_confidence,
   115→            improvement_potential,
   116→        );
   117→
   118→        self.predictions_made += 1;
   119→        outcome
   120→    }
   121→
   122→    /// 예측 결과 기반 조치 실행
   123→    pub fn execute_based_on_prediction(&mut self, outcome: &PredictionOutcome, current_timestamp: u64) -> bool {
   124→        // 신뢰도 확인
   125→        if outcome.overall_confidence < self.min_confidence_for_action {
   126→            return false;  // 신뢰도 부족: 조치 안 함
   127→        }
   128→
   129→        // 조치 스케줄
   130→        for action_name in &outcome.recommended_actions {
   131→            // 문자열을 ProactiveAction으로 변환
   132→            if self.schedule_action_by_name(action_name, current_timestamp, outcome.overall_confidence) {
   133→                self.actions_executed += 1;
   134→            }
   135→        }
   136→
   137→        true
   138→    }
   139→
   140→    /// 예측 성공/실패 기록
   141→    pub fn record_prediction_accuracy(
   142→        &mut self,
   143→        pattern_type: &str,
   144→        predicted_saturation: f64,
   145→        actual_saturation: f64,
   146→    ) {
   147→        let error = (actual_saturation - predicted_saturation).abs();
   148→        let success = error < 0.05;  // ±5% 오차
   149→
   150→        if success {
   151→            self.successful_predictions += 1;
   152→        }
   153→
   154→        // 이 정보를 나중에 모델 재학습에 사용
   155→    }
   156→
   157→    // ========================================================================
   158→    // 내부 메서드: Week 1 & Week 2 통합 로직
   159→    // ========================================================================
   160→
   161→    fn get_pattern_confidence(&self, pattern_id: u32) -> f64 {
   162→        for state in &self.pattern_states {
   163→            if state.pattern_id == pattern_id {
   164→                return state.confidence;
   165→            }
   166→        }
   167→        0.0
   168→    }
   169→
   170→    fn get_pattern_statistics(&self, pattern_type: &str) -> PatternStatistics {
   171→        for stats in &self.pattern_statistics {
   172→            if stats.pattern_type == pattern_type {
   173→                return stats.clone();
   174→            }
   175→        }
   176→
   177→        // 기본값 반환
   178→        PatternStatistics {
   179→            pattern_type: pattern_type.to_string(),
   180→            total_occurrences: 0,
   181→            success_count: 0,
   182→            failure_count: 0,
   183→            success_rate: 0.0,
   184→            average_recovery_time_ms: 0,
   185→            average_improvement_ratio: 0.0,
   186→            min_recovery_time_ms: 0,
   187→            max_recovery_time_ms: 0,
   188→            last_occurrence_timestamp: 0,
   189→        }
   190→    }
   191→
   192→    fn get_or_create_trend_predictor(&mut self, index: usize) -> &mut TrendPredictor {
   193→        while self.trend_predictors.len() <= index {
   194→            self.trend_predictors.push(TrendPredictor::new());
   195→        }
   196→        &mut self.trend_predictors[index]
   197→    }
   198→
   199→    fn estimate_time_to_critical(&self, pattern_id: u32, current_saturation: f64) -> u32 {
   200→        // 임시 구현: 선형 추정
   201→        if current_saturation > 0.95 {
   202→            0  // 이미 위기 상태
   203→        } else if current_saturation > 0.90 {
   204→            100  // 100ms 내 위기
   205→        } else if current_saturation > 0.80 {
   206→            500  // 500ms 내 위기
   207→        } else {
   208→            1000  // 1초 내 위기
   209→        }
   210→    }
   211→
   212→    fn calculate_improvement_potential(&self, pattern_type: &str, stats: &PatternStatistics) -> f64 {
   213→        // 과거 평균 개선도 활용
   214→        stats.average_improvement_ratio.min(0.5)  // 최대 50%
   215→    }
   216→
   217→    fn select_proactive_actions(
   218→        &self,
   219→        pattern_type: &str,
   220→        confidence: f64,
   221→        improvement_potential: f64,
   222→    ) -> Vec<String> {
   223→        // 패턴 타입에 따라 추천 조치 선택
   224→        match pattern_type {
   225→            "MemoryLeak" => vec!["AggressiveGC".to_string()],
   226→            "IOBottleneck" => vec!["BufferPoolExpansion".to_string()],
   227→            "ThreadContention" => vec!["ThreadPoolAdjustment".to_string()],
   228→            "CacheThreshing" => vec!["CachePreemption".to_string()],
   229→            "CombinedPressure" => vec![
   230→                "AggressiveGC".to_string(),
   231→                "BufferPoolExpansion".to_string(),
   232→                "GracefulDegradationPreload".to_string(),
   233→            ],
   234→            _ => vec![],
   235→        }
   236→    }
   237→
   238→    fn calculate_integrated_confidence(&self, pattern_confidence: f64, improvement_potential: f64) -> f64 {
   239→        // 패턴 신뢰도 (70%) + 개선 가능성 (30%)
   240→        pattern_confidence * 0.7 + improvement_potential * 0.3
   241→    }
   242→
   243→    fn schedule_action_by_name(
   244→        &mut self,
   245→        action_name: &str,
   246→        current_timestamp: u64,
   247→        confidence: f64,
   248→    ) -> bool {
   249→        // 조치 이름으로 ProactiveAction 결정
   250→        // 실제 구현에서는 더 정교한 매핑 필요
   251→        match action_name {
   252→            "AggressiveGC" => {
   253→                // 예정 시간 = 현재 + 100ms (조치 준비 시간)
   254→                self.dispatcher.dispatch_action(
   255→                    crate::predictive::proactive_dispatcher::ProactiveAction::AggressiveGC,
   256→                    current_timestamp + 100,
   257→                    confidence,
   258→                )
   259→            }
   260→            _ => false,
   261→        }
   262→    }
