   265→    // 통계 조회
   266→    // ========================================================================
   267→
   268→    pub fn get_system_health(&self) -> SystemHealth {
   269→        let success_rate = if self.predictions_made > 0 {
   270→            (self.successful_predictions as f64) / (self.predictions_made as f64)
   271→        } else {
   272→            0.0
   273→        };
   274→
   275→        SystemHealth {
   276→            predictions_made: self.predictions_made,
   277→            successful_predictions: self.successful_predictions,
   278→            success_rate,
   279→            actions_executed: self.actions_executed,
   280→            min_confidence_threshold: self.min_confidence_for_action,
   281→        }
   282→    }
   283→}
