    10→struct NodeInfo {
    11→    node_id: u32,
    12→    node_name: String,
    13→    ip_address: String,           // "127.0.0.1:8080"
    14→    port: u16,
    15→    active: bool,
    16→    last_heartbeat: u64,          // 마지막 하트비트 시간
    17→    response_time_ms: u32,        // 평균 응답 시간
    18→    trust_score: f64,             // 신뢰도 (0.0-1.0)
    19→    pattern_count: u32,           // 보유 패턴 수
    20→    prediction_accuracy: f64,     // 예측 정확도
    21→}
    22→
    23→impl NodeInfo {
    24→    fn new(node_id: u32, node_name: String, ip_address: String, port: u16) -> NodeInfo {
    25→        NodeInfo {
    26→            node_id,
    27→            node_name,
    28→            ip_address,
    29→            port,
    30→            active: true,
    31→            last_heartbeat: 0,
    32→            response_time_ms: 0,
    33→            trust_score: 0.5,          // 초기값 50%
    34→            pattern_count: 0,
    35→            prediction_accuracy: 0.0,
    36→        }
    37→    }
    38→
    39→    fn is_healthy(&self, current_timestamp: u64) -> bool {
    40→        // 30초 이내에 하트비트가 있어야 함
    41→        self.active && (current_timestamp - self.last_heartbeat) < 30000
    42→    }
    43→
    44→    fn update_trust_score(&mut self, accuracy: f64, response_time: u32) {
    45→        // 신뢰도 = 정확도 (70%) + 응답성 (30%)
    46→        let accuracy_factor = accuracy;  // 0.0-1.0
    47→        let response_factor = 1.0 - ((response_time as f64) / 1000.0).min(1.0);  // 1초 기준
    48→
    49→        self.trust_score = accuracy_factor * 0.7 + response_factor * 0.3;
    50→    }
    51→}
