    56→
    57→struct PeerDiscovery {
    58→    known_nodes: Vec<NodeInfo>,
    59→    max_nodes: usize,             // 최대 노드 수 (기본 16)
    60→    discovery_interval_ms: u32,   // 발견 주기 (기본 5000ms)
    61→    last_discovery: u64,
    62→}
    63→
    64→impl PeerDiscovery {
    65→    fn new() -> PeerDiscovery {
    66→        PeerDiscovery {
    67→            known_nodes: Vec::new(),
    68→            max_nodes: 16,
    69→            discovery_interval_ms: 5000,
    70→            last_discovery: 0,
    71→        }
    72→    }
    73→
    74→    fn register_peer(&mut self, node_info: NodeInfo) -> bool {
    75→        // 중복 확인
    76→        if self.known_nodes.iter().any(|n| n.node_id == node_info.node_id) {
    77→            return false;
    78→        }
    79→
    80→        // 최대값 확인
    81→        if self.known_nodes.len() >= self.max_nodes {
    82→            return false;
    83→        }
    84→
    85→        self.known_nodes.push(node_info);
    86→        true
    87→    }
    88→
    89→    fn unregister_peer(&mut self, node_id: u32) -> bool {
    90→        if let Some(pos) = self.known_nodes.iter().position(|n| n.node_id == node_id) {
    91→            self.known_nodes.remove(pos);
    92→            return true;
    93→        }
    94→        false
    95→    }
    96→
    97→    fn get_peer(&self, node_id: u32) -> Option<&NodeInfo> {
    98→        self.known_nodes.iter().find(|n| n.node_id == node_id)
    99→    }
   100→
   101→    fn get_healthy_peers(&self, current_timestamp: u64) -> Vec<&NodeInfo> {
   102→        self.known_nodes
   103→            .iter()
   104→            .filter(|n| n.is_healthy(current_timestamp))
   105→            .collect()
   106→    }
   107→
   108→    fn get_peer_count(&self) -> usize {
   109→        self.known_nodes.len()
   110→    }
   111→
   112→    fn get_healthy_peer_count(&self, current_timestamp: u64) -> usize {
   113→        self.get_healthy_peers(current_timestamp).len()
   114→    }
   115→
   116→    fn should_discover(&self, current_timestamp: u64) -> bool {
   117→        current_timestamp - self.last_discovery >= self.discovery_interval_ms as u64
   118→    }
   119→
   120→    fn update_discovery_time(&mut self, timestamp: u64) {
   121→        self.last_discovery = timestamp;
   122→    }
   123→}
