   125→// ============================================================================
   126→// PatternSharing: 패턴 공유
   127→// ============================================================================
   128→
   129→struct SharedPattern {
   130→    pattern_id: u32,
   131→    pattern_type: String,
   132→    source_node_id: u32,
   133→    confidence: f64,
   134→    shared_timestamp: u64,
   135→    frequency: u32,
   136→    success_rate: f64,
   137→}
   138→
   139→impl SharedPattern {
   140→    fn new(
   141→        pattern_id: u32,
   142→        pattern_type: String,
   143→        source_node_id: u32,
   144→        confidence: f64,
   145→        frequency: u32,
   146→        success_rate: f64,
   147→        timestamp: u64,
   148→    ) -> SharedPattern {
   149→        SharedPattern {
   150→            pattern_id,
   151→            pattern_type,
   152→            source_node_id,
   153→            confidence,
   154→            shared_timestamp: timestamp,
   155→            frequency,
   156→            success_rate,
   157→        }
   158→    }
   159→
   160→    fn is_fresh(&self, current_timestamp: u64) -> bool {
   161→        // 10분 이내의 패턴을 신선하다고 간주
   162→        current_timestamp - self.shared_timestamp < 600000
   163→    }
   164→
   165→    fn value_score(&self) -> f64 {
   166→        // 패턴의 가치도 = 신뢰도 (50%) + 빈도 (30%) + 성공률 (20%)
   167→        let frequency_factor = (self.frequency as f64 / 10.0).min(1.0);
   168→        self.confidence * 0.5 + frequency_factor * 0.3 + self.success_rate * 0.2
   169→    }
   170→}
   171→
   172→// ============================================================================
   173→// PatternSharingManager: 패턴 공유 관리
   174→// ============================================================================
   175→
   176→struct PatternSharingManager {
   177→    shared_patterns: Vec<SharedPattern>,
   178→    max_patterns: usize,          // 최대 공유 패턴 (기본 1000)
   179→    sharing_interval_ms: u32,     // 공유 주기 (기본 300000ms = 5분)
   180→}
   181→
   182→impl PatternSharingManager {
   183→    fn new() -> PatternSharingManager {
   184→        PatternSharingManager {
   185→            shared_patterns: Vec::new(),
   186→            max_patterns: 1000,
   187→            sharing_interval_ms: 300000,
   188→        }
   189→    }
   190→
   191→    fn share_pattern(&mut self, pattern: SharedPattern) -> bool {
   192→        // 중복 확인
   193→        if self.shared_patterns.iter().any(|p| p.pattern_id == pattern.pattern_id) {
   194→            return false;
   195→        }
   196→
   197→        // 최대값 확인
   198→        if self.shared_patterns.len() >= self.max_patterns {
   199→            // 가장 낮은 가치도의 패턴 제거
   200→            if let Some(pos) = self
   201→                .shared_patterns
   202→                .iter()
   203→                .position(|p| p.value_score() == self.shared_patterns.iter().map(|p| p.value_score()).fold(f64::INFINITY, f64::min))
   204→            {
   205→                self.shared_patterns.remove(pos);
   206→            }
   207→        }
   208→
   209→        self.shared_patterns.push(pattern);
   210→        true
   211→    }
   212→
   213→    fn get_pattern(&self, pattern_id: u32) -> Option<&SharedPattern> {
   214→        self.shared_patterns.iter().find(|p| p.pattern_id == pattern_id)
   215→    }
   216→
   217→    fn get_fresh_patterns(&self, current_timestamp: u64) -> Vec<&SharedPattern> {
   218→        self.shared_patterns
   219→            .iter()
   220→            .filter(|p| p.is_fresh(current_timestamp))
   221→            .collect()
   222→    }
   223→
   224→    fn get_patterns_by_type(&self, pattern_type: &str) -> Vec<&SharedPattern> {
   225→        self.shared_patterns
   226→            .iter()
   227→            .filter(|p| p.pattern_type == pattern_type)
   228→            .collect()
   229→    }
   230→
   231→    fn get_top_patterns(&self, count: usize) -> Vec<&SharedPattern> {
   232→        let mut sorted = self.shared_patterns.iter().collect::<Vec<_>>();
   233→        sorted.sort_by(|a, b| b.value_score().partial_cmp(&a.value_score()).unwrap());
   234→        sorted.into_iter().take(count).collect()
   235→    }
   236→
   237→    fn pattern_count(&self) -> usize {
   238→        self.shared_patterns.len()
   239→    }
   240→}
