   243→// ConsensusLearning: 합의 기반 학습
   244→// ============================================================================
   245→
   246→struct ConsensusVote {
   247→    pattern_id: u32,
   248→    pattern_type: String,
   249→    votes: Vec<(u32, f64)>,      // (node_id, confidence)
   250→    consensus_confidence: f64,
   251→    voter_count: u32,
   252→}
   253→
   254→impl ConsensusVote {
   255→    fn new(pattern_id: u32, pattern_type: String) -> ConsensusVote {
   256→        ConsensusVote {
   257→            pattern_id,
   258→            pattern_type,
   259→            votes: Vec::new(),
   260→            consensus_confidence: 0.0,
   261→            voter_count: 0,
   262→        }
   263→    }
   264→
   265→    fn add_vote(&mut self, node_id: u32, confidence: f64) {
   266→        self.votes.push((node_id, confidence));
   267→        self.voter_count += 1;
   268→        self.update_consensus();
   269→    }
   270→
   271→    fn update_consensus(&mut self) {
   272→        if self.votes.is_empty() {
   273→            self.consensus_confidence = 0.0;
   274→            return;
   275→        }
   276→
   277→        let total: f64 = self.votes.iter().map(|(_, conf)| conf).sum();
   278→        self.consensus_confidence = total / self.votes.len() as f64;
   279→    }
   280→
   281→    fn get_consensus(&self) -> f64 {
   282→        self.consensus_confidence
   283→    }
   284→
   285→    fn is_consensus_reached(&self, threshold: f64) -> bool {
   286→        self.consensus_confidence >= threshold && self.voter_count >= 3
   287→    }
   288→}
