   290→// ============================================================================
   291→// ConsensusLearningEngine: 합의 학습 엔진
   292→// ============================================================================
   293→
   294→struct ConsensusLearningEngine {
   295→    active_votes: Vec<ConsensusVote>,
   296→    completed_votes: Vec<ConsensusVote>,
   297→    consensus_threshold: f64,     // 기본 0.75 (75%)
   298→    min_voters: u32,              // 최소 투표자 수 (기본 3)
   299→}
   300→
   301→impl ConsensusLearningEngine {
   302→    fn new() -> ConsensusLearningEngine {
   303→        ConsensusLearningEngine {
   304→            active_votes: Vec::new(),
   305→            completed_votes: Vec::new(),
   306→            consensus_threshold: 0.75,
   307→            min_voters: 3,
   308→        }
   309→    }
   310→
   311→    fn initiate_vote(&mut self, pattern_id: u32, pattern_type: String) -> bool {
   312→        // 중복 확인
   313→        if self.active_votes.iter().any(|v| v.pattern_id == pattern_id) {
   314→            return false;
   315→        }
   316→
   317→        let vote = ConsensusVote::new(pattern_id, pattern_type);
   318→        self.active_votes.push(vote);
   319→        true
   320→    }
   321→
   322→    fn add_vote(&mut self, pattern_id: u32, node_id: u32, confidence: f64) -> bool {
   323→        for vote in &mut self.active_votes {
   324→            if vote.pattern_id == pattern_id {
   325→                vote.add_vote(node_id, confidence);
   326→                return true;
   327→            }
   328→        }
   329→        false
   330→    }
   331→
   332→    fn check_consensus(&mut self) -> Vec<ConsensusVote> {
   333→        let mut completed = Vec::new();
   334→
   335→        // 합의에 도달한 투표 확인
   336→        let mut i = 0;
   337→        while i < self.active_votes.len() {
   338→            if self.active_votes[i].is_consensus_reached(self.consensus_threshold) {
   339→                let vote = self.active_votes.remove(i);
   340→                self.completed_votes.push(vote.clone());
   341→                completed.push(vote);
   342→            } else {
   343→                i += 1;
   344→            }
   345→        }
   346→
   347→        completed
   348→    }
   349→
   350→    fn get_consensus_patterns(&self) -> Vec<&ConsensusVote> {
   351→        self.completed_votes.iter().collect()
   352→    }
   353→
   354→    fn get_agreement_level(&self, pattern_id: u32) -> Option<f64> {
   355→        for vote in &self.completed_votes {
   356→            if vote.pattern_id == pattern_id {
   357→                return Some(vote.consensus_confidence);
   358→            }
   359→        }
   360→        None
   361→    }
   362→
   363→    fn active_vote_count(&self) -> usize {
   364→        self.active_votes.len()
   365→    }
   366→}
