     8→// ============================================================================
     9→// AGGREGATED FORECASTING: 다중 노드 예측 통합
    10→// ============================================================================
    11→
    12→pub struct NodeForecast {
    13→    node_id: u32,
    14→    pattern_type: String,
    15→    predicted_saturation: f64,
    16→    confidence: f64,
    17→    time_to_critical: u32,
    18→    freshness_score: f64, // 예측 신선도 (0-100, 최신=100)
    19→}
    20→
    21→pub struct AggregatedForecast {
    22→    consensus_saturation: f64,     // 가중 평균 포화도
    23→    consensus_confidence: f64,      // 가중 평균 신뢰도
    24→    forecasts: Vec<NodeForecast>,   // 개별 노드 예측들
    25→    agreement_ratio: f64,           // 노드 간 일치도 (0-1)
    26→    prediction_variance: f64,       // 포화도 예측 분산
    27→    is_reliable: bool,              // 신뢰도 임계값(75%) 통과 여부
    28→}
    29→
    30→pub struct AggregatedForecasting {
    31→    min_node_agreement: f64,        // 신뢰할 최소 노드 일치도 (기본: 0.6)
    32→    confidence_weight: f64,         // 신뢰도 가중치 (기본: 0.5)
    33→    freshness_weight: f64,          // 신선도 가중치 (기본: 0.3)
    34→    recency_weight: f64,            // 최근성 가중치 (기본: 0.2)
    35→}
    36→
    37→impl AggregatedForecasting {
    38→    pub fn new() -> Self {
    39→        AggregatedForecasting {
    40→            min_node_agreement: 0.6,
    41→            confidence_weight: 0.5,
    42→            freshness_weight: 0.3,
    43→            recency_weight: 0.2,
    44→        }
    45→    }
    46→
    47→    // 다중 노드 예측을 통합하여 집계 예측 생성
    48→    pub fn aggregate_forecasts(
    49→        &self,
    50→        forecasts: &Vec<NodeForecast>,
    51→        current_time: u64,
    52→        node_trust_scores: &HashMap<u32, f64>,
    53→    ) -> AggregatedForecast {
    54→        if forecasts.len() == 0 {
    55→            return AggregatedForecast {
    56→                consensus_saturation: 0.0,
    57→                consensus_confidence: 0.0,
    58→                forecasts: vec![],
    59→                agreement_ratio: 0.0,
    60→                prediction_variance: 0.0,
    61→                is_reliable: false,
    62→            };
    63→        }
    64→
    65→        // 1. 각 예측에 가중치 적용
    66→        let mut weighted_saturation = 0.0;
    67→        let mut weighted_confidence = 0.0;
    68→        let mut total_weight = 0.0;
    69→        let mut saturation_values = vec![];
    70→
    71→        for forecast in forecasts {
    72→            // 노드 신뢰도 기반 가중치 (기본: 1.0)
    73→            let trust_weight = match node_trust_scores.get(&forecast.node_id) {
    74→                Some(&score) => score,
    75→                None => 1.0,
    76→            };
    77→
    78→            // 신뢰도 + 신선도 + 최근성 복합 가중치
    79→            let composite_weight = trust_weight
    80→                * (forecast.confidence * self.confidence_weight
    81→                    + forecast.freshness_score / 100.0 * self.freshness_weight
    82→                    + (1.0 - self.recency_weight)); // 모두 최근 예측이라고 가정
    83→
    84→            weighted_saturation += forecast.predicted_saturation * composite_weight;
    85→            weighted_confidence += forecast.confidence * composite_weight;
    86→            total_weight += composite_weight;
    87→            saturation_values.push(forecast.predicted_saturation);
    88→        }
    89→
    90→        let consensus_saturation = if total_weight > 0.0 {
    91→            weighted_saturation / total_weight
    92→        } else {
    93→            0.0
    94→        };
    95→
    96→        let consensus_confidence = if total_weight > 0.0 {
    97→            weighted_confidence / total_weight
    98→        } else {
    99→            0.0
   100→        };
   101→
   102→        // 2. 노드 간 일치도 계산 (표준편차 기반)
   103→        let mean_saturation = consensus_saturation;
   104→        let variance = saturation_values
   105→            .iter()
   106→            .map(|&v| (v - mean_saturation).powi(2))
   107→            .sum::<f64>()
   108→            / saturation_values.len() as f64;
   109→        let std_dev = variance.sqrt();
   110→
   111→        // 일치도: 표준편차가 작을수록 높음 (0-1 범위)
   112→        let agreement_ratio = (1.0 / (1.0 + std_dev)).min(1.0);
   113→
   114→        // 3. 신뢰성 판정 (합의도 >= 최소 임계값)
   115→        let is_reliable = agreement_ratio >= self.min_node_agreement
   116→            && consensus_confidence >= 0.75;
   117→
   118→        AggregatedForecast {
   119→            consensus_saturation,
   120→            consensus_confidence,
   121→            forecasts: forecasts.clone(),
   122→            agreement_ratio,
   123→            prediction_variance: variance,
   124→            is_reliable,
   125→        }
   126→    }
   127→
   128→    // 예측 신선도 점수 계산 (최대 100)
   129→    pub fn calculate_freshness_score(
   130→        &self,
   131→        prediction_age_seconds: u64,
   132→    ) -> f64 {
   133→        let decay_constant = 300.0; // 300초 반감기
   134→        let freshness = 100.0 * (-1.0 * prediction_age_seconds as f64 / decay_constant).exp();
   135→        freshness.max(0.0).min(100.0)
   136→    }
   137→}
