   139→// ============================================================================
   140→// WEIGHTED VOTING: 신뢰도 기반 가중 투표 시스템
   141→// ============================================================================
   142→
   143→pub enum VotingDecision {
   144→    ExecuteAction,          // 즉시 조치 (consensus >= 85%)
   145→    PrepareAction,          // 준비 단계 (consensus >= 70%)
   146→    Monitor,                // 모니터링 만 진행
   147→    Conflict,               // 노드 간 심각한 불일치
   148→}
   149→
   150→pub struct Vote {
   151→    node_id: u32,
   152→    decision: String,       // "execute", "prepare", "monitor"
   153→    confidence: f64,
   154→    reasoning: String,
   155→}
   156→
   157→pub struct WeightedVote {
   158→    votes: Vec<Vote>,
   159→    execution_votes: u32,
   160→    prepare_votes: u32,
   161→    monitor_votes: u32,
   162→    weighted_execute_confidence: f64,
   163→    weighted_prepare_confidence: f64,
   164→    consensus_strength: f64, // 최강 투표 비중
   165→}
   166→
   167→pub struct WeightedVoting {
   168→    execute_threshold: f64,  // 기본: 0.85
   169→    prepare_threshold: f64,  // 기본: 0.70
   170→    min_voting_nodes: u32,   // 기본: 3
   171→}
   172→
   173→impl WeightedVoting {
   174→    pub fn new() -> Self {
   175→        WeightedVoting {
   176→            execute_threshold: 0.85,
   177→            prepare_threshold: 0.70,
   178→            min_voting_nodes: 3,
   179→        }
   180→    }
   181→
   182→    // 가중 투표 수행 및 결정 내림
   183→    pub fn conduct_weighted_voting(
   184→        &self,
   185→        votes: &Vec<Vote>,
   186→        node_trust_scores: &HashMap<u32, f64>,
   187→    ) -> (WeightedVote, VotingDecision) {
   188→        let mut execution_votes = 0u32;
   189→        let mut prepare_votes = 0u32;
   190→        let mut monitor_votes = 0u32;
   191→        let mut weighted_execute_confidence = 0.0;
   192→        let mut weighted_prepare_confidence = 0.0;
   193→        let mut total_weight = 0.0;
   194→
   195→        for vote in votes {
   196→            let node_trust = match node_trust_scores.get(&vote.node_id) {
   197→                Some(&score) => score,
   198→                None => 1.0,
   199→            };
   200→
   201→            let weighted_confidence = vote.confidence * node_trust;
   202→            total_weight += node_trust;
   203→
   204→            match vote.decision.as_str() {
   205→                "execute" => {
   206→                    execution_votes += 1;
   207→                    weighted_execute_confidence += weighted_confidence;
   208→                }
   209→                "prepare" => {
   210→                    prepare_votes += 1;
   211→                    weighted_prepare_confidence += weighted_confidence;
   212→                }
   213→                _ => {
   214→                    monitor_votes += 1;
   215→                }
   216→            }
   217→        }
   218→
   219→        // 정규화
   220→        if total_weight > 0.0 {
   221→            weighted_execute_confidence /= total_weight;
   222→            weighted_prepare_confidence /= total_weight;
   223→        }
   224→
   225→        // 합의 강도 (최강 투표 비중)
   226→        let max_votes = execution_votes.max(prepare_votes).max(monitor_votes) as f64;
   227→        let consensus_strength = if votes.len() > 0 {
   228→            max_votes / votes.len() as f64
   229→        } else {
   230→            0.0
   231→        };
   232→
   233→        let weighted_vote = WeightedVote {
   234→            votes: votes.clone(),
   235→            execution_votes,
   236→            prepare_votes,
   237→            monitor_votes,
   238→            weighted_execute_confidence,
   239→            weighted_prepare_confidence,
   240→            consensus_strength,
   241→        };
   242→
   243→        // 의사결정
   244→        let decision = if votes.len() < self.min_voting_nodes as usize {
   245→            VotingDecision::Monitor // 최소 투표 노드 미달
   246→        } else if weighted_execute_confidence >= self.execute_threshold {
   247→            VotingDecision::ExecuteAction
   248→        } else if weighted_prepare_confidence >= self.prepare_threshold {
   249→            VotingDecision::PrepareAction
   250→        } else if consensus_strength < 0.5 {
   251→            VotingDecision::Conflict // 심각한 불일치
   252→        } else {
   253→            VotingDecision::Monitor
   254→        };
   255→
   256→        (weighted_vote, decision)
   257→    }
   258→}
