   260→// ============================================================================
   261→// CONFLICT RESOLUTION: 노드 간 의견 불일치 해결
   262→// ============================================================================
   263→
   264→pub enum ConflictType {
   265→    ExecuteVsPrepare,       // Execute 투표 vs Prepare 투표
   266→    HighVariance,           // 예측값 분산이 높음
   267→    TrustMismatch,          // 신뢰도와 의견이 불일치
   268→    DeadlockVoting,         // 동등 분할 투표
   269→}
   270→
   271→pub struct ConflictInfo {
   272→    conflict_type: ConflictType,
   273→    affected_nodes: u32,
   274→    severity: f64,          // 0-1, 높을수록 심각
   275→    recommended_resolution: String,
   276→}
   277→
   278→pub struct ConflictResolution {
   279→    tie_breaker_enabled: bool,
   280→    leader_trust_boost: f64, // 리더 신뢰도 보너스 (기본: 0.1)
   281→    escalation_factor: f64,  // 심각도 가중치 (기본: 1.5)
   282→}
   283→
   284→impl ConflictResolution {
   285→    pub fn new() -> Self {
   286→        ConflictResolution {
   287→            tie_breaker_enabled: true,
   288→            leader_trust_boost: 0.1,
   289→            escalation_factor: 1.5,
   290→        }
   291→    }
   292→
   293→    // 충돌 감지 및 해결
   294→    pub fn detect_and_resolve_conflicts(
   295→        &self,
   296→        aggregated: &AggregatedForecast,
   297→        weighted_vote: &WeightedVote,
   298→        leader_node_id: Option<u32>,
   299→    ) -> (Option<ConflictInfo>, VotingDecision) {
   300→        let total_votes = weighted_vote.execution_votes
   301→            + weighted_vote.prepare_votes
   302→            + weighted_vote.monitor_votes;
   303→
   304→        // 1. 충돌 유형 감지
   305→        let conflict_type = if (weighted_vote.execution_votes as f64 - weighted_vote.prepare_votes as f64).abs()
   306→            < total_votes as f64 * 0.1
   307→        {
   308→            Some(ConflictType::ExecuteVsPrepare)
   309→        } else if aggregated.prediction_variance > 0.15 {
   310→            Some(ConflictType::HighVariance)
   311→        } else if (aggregated.agreement_ratio - aggregated.consensus_confidence).abs() > 0.2 {
   312→            Some(ConflictType::TrustMismatch)
   313→        } else if weighted_vote.consensus_strength < 0.55 {
   314→            Some(ConflictType::DeadlockVoting)
   315→        } else {
   316→            None
   317→        };
   318→
   319→        match conflict_type {
   320→            Some(conflict) => {
   321→                // 심각도 계산
   322→                let severity = match conflict {
   323→                    ConflictType::ExecuteVsPrepare => 0.4,
   324→                    ConflictType::HighVariance => 0.6,
   325→                    ConflictType::TrustMismatch => 0.5,
   326→                    ConflictType::DeadlockVoting => 0.7,
   327→                };
   328→
   329→                let severity_scaled = severity * self.escalation_factor;
   330→
   331→                // 2. 해결 권장사항
   332→                let recommended = match conflict {
   333→                    ConflictType::ExecuteVsPrepare => {
   334→                        "리더 노드의 투표를 우선 반영하거나 준비 단계로 보수적 선택"
   335→                    }
   336→                    ConflictType::HighVariance => {
   337→                        "노드 간 데이터 동기화 수행 후 재투표"
   338→                    }
   339→                    ConflictType::TrustMismatch => {
   340→                        "저신뢰도 노드의 투표 가중치 재평가"
   341→                    }
   342→                    ConflictType::DeadlockVoting => {
   343→                        "모니터링 강화 및 추가 증거 수집"
   344→                    }
   345→                };
   346→
   347→                let conflict_info = ConflictInfo {
   348→                    conflict_type: conflict,
   349→                    affected_nodes: aggregated.forecasts.len() as u32,
   350→                    severity: severity_scaled.min(1.0),
   351→                    recommended_resolution: recommended.to_string(),
   352→                };
   353→
   354→                // 3. Tie-breaker (리더 존재 시)
   355→                let resolution_decision = if self.tie_breaker_enabled && leader_node_id.is_some() {
   356→                    // 리더의 투표 신뢰도에 보너스 적용
   357→                    VotingDecision::Monitor // 재평가 후 재투표
   358→                } else {
   359→                    VotingDecision::Monitor // 모니터링 모드로 전환
   360→                };
   361→
   362→                (Some(conflict_info), resolution_decision)
   363→            }
   364→            None => (None, VotingDecision::ExecuteAction), // 충돌 없음
   365→        }
   366→    }
   367→
   368→    // Tie-breaker: 리더 노드의 신뢰도를 임시로 상향 조정
   369→    pub fn apply_leader_tie_break(
   370→        &self,
   371→        leader_trust_score: f64,
   372→    ) -> f64 {
   373→        (leader_trust_score + self.leader_trust_boost).min(1.0)
   374→    }
   375→}
   376→
   377→// ============================================================================
   378→// DISTRIBUTED PREDICTION SYSTEM: 통합 분산 예측 시스템
   379→// ============================================================================
   380→
   381→pub struct DistributedPredictionSystem {
   382→    aggregating: AggregatedForecasting,
   383→    voting: WeightedVoting,
   384→    conflict_resolution: ConflictResolution,
   385→    last_decision: Option<VotingDecision>,
   386→    decision_history: Vec<(u64, String)>, // (timestamp, decision_type)
   387→}
   388→
   389→impl DistributedPredictionSystem {
   390→    pub fn new() -> Self {
   391→        DistributedPredictionSystem {
   392→            aggregating: AggregatedForecasting::new(),
   393→            voting: WeightedVoting::new(),
   394→            conflict_resolution: ConflictResolution::new(),
   395→            last_decision: None,
   396→            decision_history: vec![],
   397→        }
   398→    }
   399→
   400→    // 전체 분산 예측 파이프라인 실행
   401→    pub fn execute_distributed_prediction(
   402→        &mut self,
   403→        node_forecasts: &Vec<NodeForecast>,
   404→        votes: &Vec<Vote>,
   405→        node_trust_scores: &HashMap<u32, f64>,
   406→        leader_node_id: Option<u32>,
   407→        current_time: u64,
   408→    ) -> (AggregatedForecast, WeightedVote, Option<ConflictInfo>, VotingDecision) {
   409→        // 1. 예측 통합 (Aggregation)
   410→        let aggregated = self.aggregating.aggregate_forecasts(
   411→            node_forecasts,
   412→            current_time,
   413→            node_trust_scores,
   414→        );
   415→
   416→        // 2. 가중 투표 (Voting)
   417→        let (weighted_vote, initial_decision) =
   418→            self.voting.conduct_weighted_voting(votes, node_trust_scores);
   419→
   420→        // 3. 충돌 해결 (Conflict Resolution)
   421→        let (conflict_info, final_decision) =
   422→            self.conflict_resolution.detect_and_resolve_conflicts(
   423→                &aggregated,
   424→                &weighted_vote,
   425→                leader_node_id,
   426→            );
   427→
   428→        // 의사결정 이력 기록
   429→        let decision_str = match final_decision {
   430→            VotingDecision::ExecuteAction => "execute".to_string(),
   431→            VotingDecision::PrepareAction => "prepare".to_string(),
   432→            VotingDecision::Monitor => "monitor".to_string(),
   433→            VotingDecision::Conflict => "conflict".to_string(),
   434→        };
   435→
   436→        self.decision_history.push((current_time, decision_str));
   437→        self.last_decision = Some(final_decision);
   438→
   439→        (aggregated, weighted_vote, conflict_info, final_decision)
   440→    }
   441→
   442→    // 의사결정 히스토리 조회
   443→    pub fn get_decision_history(&self) -> &Vec<(u64, String)> {
   444→        &self.decision_history
   445→    }
   446→
   447→    // 마지막 의사결정 조회
   448→    pub fn get_last_decision(&self) -> Option<&VotingDecision> {
   449→        self.last_decision.as_ref()
   450→    }
   451→}
