   222→    // Helper function: 표준편차 계산
   223→    fn calculate_stddev(values: &[u32], mean: u32) -> f64 {
   224→        let variance: f64 = values
   225→            .iter()
   226→            .map(|&v| ((v as f64 - mean as f64).powi(2)))
   227→            .sum::<f64>() / values.len() as f64;
   228→        variance.sqrt()
   229→    }
   230→}
